begin;
do $$
declare tid uuid:=gen_random_uuid(); aid uuid:=gen_random_uuid(); uid uuid; other_uid uuid; r jsonb; j balance_free_coaching_jobs; g balance_free_starters; pid uuid; before_program jsonb; token text;
 review jsonb; receipt jsonb:='{"support_access_verified":true,"invitation_verified":true,"program_preservation_verified":true,"onboarding_verified":true,"inbox_path_verified":true,"verification_summary":"controlled rollback fixture","visual_proof":"controlled fixture"}';
begin
 select id into uid from users where is_test_account and not exists(select 1 from balance_free_starters where user_id=users.id) and not exists(select 1 from ig_threads where linked_user_id=users.id) and not exists(select 1 from coach_clients where client_id=users.id) and not exists(select 1 from custom_workout_programs where user_id=users.id) limit 1;
 select id into other_uid from users where is_test_account and id<>uid limit 1;
 if uid is null or other_uid is null then raise exception 'Two controlled test users required'; end if;
 insert into ig_threads(id,coach_id,ig_username,profile_name,channel,subscriber_id,custom_data) values(tid,'00a6605e-8edb-4917-85ba-24a23f179059','support_test_'||tid,'Controlled support test','instagram','internal:'||tid,'{}');
 insert into ig_messages(id,thread_id,direction,text,source) values(aid,tid,'in','Yes to weekly check-ins alongside my trainer','internal_rollback_test');
 review:=jsonb_build_object('full_thread_reviewed',true,'support_only_accepted',true,'preserve_external_training',true,'independent_holds_checked',true,'no_reminder_consent_assumed',true,'reviewed_by','controlled fixture','support_summary','Keep external trainer; short weekly check-in','source_message_ids',jsonb_build_array(aid));
 begin perform prepare_balance_support_coaching(tid,aid,'Australia/Sydney','fixture',review); raise exception 'FAIL unreserved'; exception when raise_exception then if sqlerrm='FAIL unreserved' then raise; end if; end;
 insert into balance_coaching_challenge_enrolments(intake_id,thread_id,identity_key,acceptance_message_id,review) values('consistency_20261025',tid,'controlled:'||tid,aid,review);
 begin perform prepare_balance_support_coaching(tid,aid,'Australia/Sydney','fixture',review||'{"support_only_accepted":false}'); raise exception 'FAIL consent'; exception when raise_exception then if sqlerrm='FAIL consent' then raise; end if; end;
 begin perform prepare_balance_support_coaching(tid,aid,'Australia/Sydney','fixture',review||jsonb_build_object('source_message_ids',jsonb_build_array(gen_random_uuid()))); raise exception 'FAIL provenance'; exception when raise_exception then if sqlerrm='FAIL provenance' then raise; end if; end;
 update ig_threads set custom_data='{"human_takeover":true}' where id=tid;
 begin perform prepare_balance_support_coaching(tid,aid,'Australia/Sydney','fixture',review); raise exception 'FAIL hold'; exception when raise_exception then if sqlerrm='FAIL hold' then raise; end if; end;
 update ig_threads set custom_data='{}' where id=tid;
 r:=prepare_balance_support_coaching(tid,aid,'Australia/Sydney','fixture',review);
 if r#>>'{setup,id}' is distinct from prepare_balance_support_coaching(tid,aid,'Australia/Sydney','fixture',review)#>>'{setup,id}' then raise exception 'FAIL duplicate preparation'; end if;
 select * into j from balance_free_coaching_jobs where id=(r#>>'{job,id}')::uuid;
 token:=split_part(r#>>'{setup,invitation_url}','#invite=',2);
 begin perform claim_balance_free_starter(uid,encode(extensions.digest(token,'sha256'),'hex')); raise exception 'FAIL premature claim'; exception when raise_exception then if sqlerrm='FAIL premature claim' then raise; end if; end;
 if finish_balance_support_coaching(j.id,gen_random_uuid(),'fixture',receipt) or finish_balance_support_coaching(j.id,j.claim_token,'fixture','{}') then raise exception 'FAIL unverified finish'; end if;
 if not finish_balance_support_coaching(j.id,j.claim_token,'fixture',receipt) then raise exception 'FAIL verified finish'; end if;
 insert into custom_workout_programs(user_id,program_name,duration_weeks,weekly_schedule,is_active,start_date) values(uid,'Preserve trainer programme',4,'[]',true,current_date) returning id into pid;
 select to_jsonb(p) into before_program from custom_workout_programs p where id=pid;
 select * into g from claim_balance_free_starter(uid,encode(extensions.digest(token,'sha256'),'hex'));
 if g.ends_at<>g.starts_at+interval '28 days' or g.user_id<>uid then raise exception 'FAIL exact access'; end if;
 if (select to_jsonb(p) from custom_workout_programs p where id=pid) is distinct from before_program or (select count(*) from custom_workout_programs where user_id=uid)<>1 then raise exception 'FAIL preservation'; end if;
 perform claim_balance_free_starter(uid,encode(extensions.digest(token,'sha256'),'hex'));
 if (select starts_at from balance_free_starters where id=g.id)<>g.starts_at then raise exception 'FAIL retry extends access'; end if;
 begin perform claim_balance_free_starter(other_uid,encode(extensions.digest(token,'sha256'),'hex')); raise exception 'FAIL wrong account'; exception when raise_exception then if sqlerrm='FAIL wrong account' then raise; end if; end;
 update balance_free_starters set ends_at=now()-interval '1 second' where id=g.id;
 begin perform claim_balance_free_starter(uid,encode(extensions.digest(token,'sha256'),'hex')); raise exception 'FAIL expiry'; exception when raise_exception then if sqlerrm='FAIL expiry' then raise; end if; end;
 if has_function_privilege('authenticated','public.prepare_balance_support_coaching(uuid,uuid,text,text,jsonb)','execute') or has_function_privilege('anon','public.finish_balance_support_coaching(uuid,uuid,text,jsonb)','execute') then raise exception 'FAIL permissions'; end if;
 raise notice 'PASS support-only preservation, exact expiry, source/hold/consent/lease/identity gates and idempotency';
end $$;
rollback;
